SELECT id, key_value, key_name, device_id, permissions, status,
       rate_limit, last_used_at, expired_at, created_at, revoked_at
FROM t_api_key WHERE id = #{id}

SELECT id, key_value, key_name, device_id, permissions, status,
       rate_limit, last_used_at, expired_at, created_at, revoked_at
FROM t_api_key WHERE key_value = #{keyValue}

SELECT id, key_value, key_name, device_id, permissions, status,
       rate_limit, last_used_at, expired_at, created_at, revoked_at
FROM t_api_key WHERE device_id = #{deviceId}

mapper.update:
UPDATE t_api_key
SET key_name = #{keyName},
    permissions = #{permissions},
    rate_limit = #{rateLimit},
    expired_at = #{expiredAt}
WHERE id = #{id}
